-- Peliqan "My Queries".kpi_registry (table_id 1416381), stand 2026-11-12 vóór de AFC-tegelwijziging
SELECT
  *
FROM (VALUES
  (1, 'bruto_marge_per_loonkosten', 'Bruto marge per loonkosten', 'strategisch', 'Financiële gezondheid', 'Floor / Frits', 'Frits', 'Cashweb', 'ratio', 'hoger_beter', 'live', 'Kalenderjaar tot en met de laatste afgesloten maand', 'Maandelijks, na afsluiting van de maand', 1, 'kpi_bm_tegel', 'kpi_bm_maand', 'Omzet (rubriek 8) min inkoop (rubriek 6), gedeeld door loonkosten volgens de lijst van Frits plus uitzendkrachten (4517). Alleen entiteiten met eigen personeel.', CAST(NULL AS TEXT), 1, CAST('2026-09-21' AS DATE), 'Sprint 3: 4517 toegevoegd. Loonbasis ter bevestiging (lijst Frits of 40xx).', 'Loonbasis is de lijst van Frits plus uitzendkrachten (4517). Elke entiteit toont haar eigen laatste afgesloten maand; het concern de laatste maand waarin alle entiteiten zijn afgesloten.'),
  (2, 'triple_lob', '% Triple LOB', 'strategisch', 'Waarde', 'Floor', 'Floor', 'Cashweb', 'procent', 'hoger_beter', 'live', 'Twaalf maanden tot en met de laatste afgesloten maand', 'Maandelijks, na afsluiting van de maand', 1, 'kpi_triple_lob_tegel', 'kpi_triple_lob_maand', 'Aandeel klanten met omzet (rubriek 8, zonder accijns) bij AWC, AFC en ACC in hetzelfde venster van twaalf maanden. Klanten gekoppeld op genormaliseerde zoeknaam; twijfelgevallen beoordeeld in kpi_triple_lob_beoordeling. Waarde telt alleen zeker; met zelfde concern staat in de toelichting.', 'Nieuwe triple-matches krijgen status te_controleren tot ze in kpi_triple_lob_beoordeling staan. Werklijst: kpi_triple_lob_te_controleren.', 2, CAST('2026-09-21' AS DATE), 'v1 (bouwbriefing deel 2): vast op 2024-2025, klant_koppeltabel_lob. v2: rollend venster van 12 maanden, omzet via verkoopdagboek, 17 nieuwe matches beoordeeld door Chloë (Floor akkoord met aanpak).', 'Nog niet beoordeelde matches tellen niet mee als zeker. Klanten met dezelfde zoeknaam zijn dezelfde klant, tenzij afgekeurd.'),
  (3, 'winrate', 'Winrate', 'strategisch', 'Commercieel', 'Mark', 'Mark', 'HubSpot', 'procent', 'hoger_beter', 'live', 'Deals aangemaakt in de laatste 12 maanden met een uitkomst, per pijplijn', 'Dagelijks (HubSpot-sync)', 20, 'kpi_winrate_tegel', 'kpi_winrate_maand', 'Gewonnen gedeeld door gewonnen plus verloren. In de Verkooppijplijn tellen Eerste levering en Opdracht als gewonnen; zie kpi_winrate_fases.', 'Trendbreuk september 2026: opschoning van de pijplijn, veel oude deals in een keer op verloren gezet.', 2, CAST('2026-09-21' AS DATE), 'v1 (bouwbriefing deel 1): alleen de HubSpot-vlaggen, zonder venster. v2: Opdracht telt als gewonnen, bevestigd 21 sep 2026, plus venster van 12 maanden.', 'De daling in september komt door de opschoning van de pijplijn, niet door slechtere verkoop. Het niveau vanaf september is het nieuwe vergelijkingspunt.'),
  (4, 'churn', 'Churn', 'strategisch', 'Retentie', 'Mark / Floor', 'Mark', 'HubSpot', 'aantal', 'lager_beter', 'live', 'Afgelopen 12 maanden, tegenover de 12 daarvoor; reeks per kwartaal', 'Dagelijks (HubSpot-sync), reeks per kwartaal', 1, 'kpi_hs_tegel', 'kpi_churn_kwartaal', 'Bedrijven met een vertrekdatum (hs_v2_date_exited_customer) in het venster. ICP-variant: 4 of meer van de 5 criteria op Yes (EU-hub, meerjarig, non-EU naar EU, premium/compliance, producent/brand owner). Het veld geografische focus telt niet mee.', 'Vertrekdatum is het moment van registratie in HubSpot, niet het echte vertrek. Dagen met 10 of meer vertrekken gelden als bulkcorrectie en worden apart getoond.', 2, CAST('2026-09-21' AS DATE), 'v1: definitie briefing deel 4. v2: gebouwd, met bulkmarkering en ICP op vijf criteria.', 'Een vertrekdatum in HubSpot betekent dat de klant echt weg is, ook als die in bulk is ingevoerd. ICP geldt alleen voor klanten met een ICP-score (27%).'),
  (5, 'otif', 'OTIF', 'strategisch', 'Operatie', 'Edo', 'Edo', '7T', 'procent', 'hoger_beter', 'tbd', 'Nog vast te stellen', 'Nog vast te stellen', 1, CAST(NULL AS TEXT), CAST(NULL AS TEXT), 'On time in full. De oorspronkelijke leverbelofte wordt in 7T overschreven; definitie volgt uit de sessie met Edo.', CAST(NULL AS TEXT), 0, CAST(NULL AS DATE), CAST(NULL AS TEXT), 'On time tegen de eerst bevestigde leverdatum uit de datumhistorie (Order_Leverdata); in full op orderregelniveau.'),
  (6, 'omzet_brug', 'Omzetbrug', 'strategisch', 'Waarde', 'Mark', 'Frits', 'Cashweb', 'euro', 'hoger_beter', 'live', 'Afgelopen 12 afgesloten maanden tegenover de 12 daarvoor', 'Maandelijks, na afsluiting van de maand', 1, 'kpi_omzetbrug_tegel', 'kpi_omzet_lob', 'Omzet (rubriek 8, zonder accijns 802001) van AWC, AFC en ACC aan externe klanten, twaalf afgesloten maanden tegenover de twaalf daarvoor, uitgesplitst naar nieuwe, gegroeide, gekrompen en verloren klanten. Klanten gekoppeld over de entiteiten heen op genormaliseerde zoeknaam; afgekeurde koppelingen en lege zoeknamen tellen per relatie. Omzet tussen de eigen entiteiten telt niet mee (kpi_intercompany).', 'Brug plus intercompany sluit op het grootboek.', 2, CAST('2026-09-22' AS DATE), 'v1: gebouwd, sluit op het grootboek. v2: intercompany eruit (aanname, ter bevestiging bij Frits); concern 19,40 naar 19,04 mln.', 'Omzet tussen AWC, AFC en ACC is geen klantomzet en telt niet mee (zes relaties in kpi_intercompany). Stelz is één klant.'),
  (7, 'ebitda', 'EBITDA', 'strategisch', 'Financiële gezondheid', 'Frits', 'Frits', 'Cashweb', 'euro', 'hoger_beter', 'live', 'Afgelopen 12 afgesloten maanden tegenover de 12 daarvoor', 'Dagelijks (Cashweb-sync), maandcijfer na afsluiting van de maand', 1, 'kpi_ebitda_tegel', 'kpi_ebitda_maand', 'Omzet (8xxx) min alle kosten in 4xxx en 6xxx, zonder afschrijvingen (42xx) en zonder rente en bankkosten (47xx en 49xx). Dat is gelijk aan resultaat na belasting plus rente, belastingen en afschrijvingen, de definitie uit de SAR-waardering van Frits. Boekingen tellen in hun boekjaar; correcties met een datum buiten het boekjaar vallen in januari of december. Kostengroepen per maand in kpi_kosten_maand.', 'Sluit per boekjaar op de SAR-waardering: concern 2025 -0,1%, ACC 2024 exact. AWC 2024 -4,4% door boekingen na afsluiting; AFC 2025 op voorlopige SAR-cijfers. Boekjaar 2026 is nog niet afgesloten; eindejaarscorrecties volgen.', 3, CAST('2026-09-22' AS DATE), 'v1: handmatige kwartaalkaart. v2: jaarcijfers uit de SAR-sheets. v3: maandelijks uit Cashweb met de SAR-definitie; de SAR-cijfers blijven als jaarcontrole in kpi_controles.', 'De maandcijfers 2026 zijn representatief, ook al is het boekjaar nog niet afgesloten. Het concerncijfer is de som van de drie entiteiten, zonder eliminatie van onderlinge posten.'),
  (8, 'ab_players', 'A/B Players', 'strategisch', 'Mensen', 'Daphne', 'Daphne', 'Handmatig', 'procent', 'hoger_beter', 'handmatig', 'Per kwartaal', 'Per kwartaal, na de vlootschouw', 1, CAST(NULL AS TEXT), CAST(NULL AS TEXT), 'Handmatig ingevoerd tot Hooray gekoppeld is.', CAST(NULL AS TEXT), 1, CAST(NULL AS DATE), CAST(NULL AS TEXT), 'Aandeel medewerkers met A- of B-beoordeling in de laatste vlootschouw, voor het concern als geheel.'),
  (9, 'enps', 'eNPS', 'tactisch', 'Mensen', 'Daphne', 'Daphne', 'Handmatig', 'score', 'hoger_beter', 'handmatig', 'Per meting', 'Per meting', 10, CAST(NULL AS TEXT), CAST(NULL AS TEXT), 'Handmatig ingevoerd tot Microsoft Forms gekoppeld is.', CAST(NULL AS TEXT), 1, CAST(NULL AS DATE), CAST(NULL AS TEXT), 'Standaard eNPS: promotors (9 en 10) min criticasters (0 tot en met 6), in procentpunten. Pas vanaf 10 antwoorden een score.'),
  (10, 'dock_to_stock', 'Dock-to-stock binnen 24 uur', 'team_awc', 'Operatie', 'Edo', 'Edo', '7T', 'procent', 'hoger_beter', 'live', 'Inbounds gelost in de laatste afgelopen maand', 'Nachtelijk uit 7T, maandcijfer na afloop van de maand', 30, 'kpi_d2s_tegel', 'kpi_d2s_maand', 'Aandeel inbounds met een doorlooptijd van 24 uur of minder, van Los_Datum tot de eerste verplaatsing met status 30 (MutatieDatum). Alleen inbounds met een verplaatsing.', 'Inbounds zonder verplaatsing (circa 39%, augustus 47%) tellen niet mee; vraag bij Edo loopt. De sprong naar 88% in augustus valt samen met minder inbounds met een verplaatsing.', 2, CAST('2026-09-21' AS DATE), 'v1: bouwbriefing deel 3. v2: nachtapp kpi_7t_naar_warehouse schrijft naar kpi_data.dock_to_stock_maand; sluit op benchmark 74,6% (2026: 74,4%).', 'Inbounds zonder verplaatsing zijn eigenaarswissels of cross-dock en vallen terecht buiten de meting. Status 30 betekent dat de pallet in de stelling staat.'),
  (11, 'nps', 'NPS, intern en extern', 'tactisch', 'Klant', 'MT', 'MT', 'Nog geen bron', 'score', 'hoger_beter', 'gepland_2027', 'Vanaf 2027', 'Nog vast te stellen', 30, CAST(NULL AS TEXT), CAST(NULL AS TEXT), 'Er loopt geen doorlopende meting. In te vullen vanaf 2027.', 'Kwartaalsessie 21 sep: tijdelijk van het dashboard.', 0, CAST(NULL AS DATE), CAST(NULL AS TEXT), CAST(NULL AS TEXT)),
  (12, 'automatiseringsdoelen', '% behaalde automatiseringsdoelen', 'tactisch', 'Efficiëntie', 'MT', 'MT', 'Nog geen bron', 'procent', 'hoger_beter', 'gepland_2027', 'Vanaf 2027', 'Per kwartaal', 1, CAST(NULL AS TEXT), CAST(NULL AS TEXT), 'Er is nog geen lijst met doelen om tegen af te zetten. In te vullen vanaf 2027.', 'Kwartaalsessie 21 sep: tijdelijk van het dashboard.', 0, CAST(NULL AS DATE), CAST(NULL AS TEXT), CAST(NULL AS TEXT)),
  (13, 'acc_dossiers', 'Dossiers per soort', 'team_acc', 'Operatie', 'Mesut', 'Mesut', 'HubSpot', 'aantal', 'neutraal', 'live', 'Kalenderjaar tot nu; reeks per maand', 'Dagelijks (HubSpot-sync)', 1, 'kpi_hs_tegel', 'kpi_acc_dossiers_maand', 'Tickets in de Customs Pipeline, geteld op aanmaakdatum, per type_aanvraag: Import, Export, Consult, Overig (Other en leeg). Geen totaalregel in de grafiek.', 'Overig groeit sinds mei 2026 sterk; navragen bij ACC wat daaronder valt.', 1, CAST('2026-09-21' AS DATE), 'Gebouwd volgens briefing deel 4.', 'Overig zijn echte dossiers waarvan het type niet is ingevuld of Other is; ze tellen mee in het totaal.'),
  (14, 'acc_doorlooptijd', 'Doorlooptijd dossier', 'team_acc', 'Operatie', 'Mesut', 'Mesut', 'HubSpot', 'dagen', 'lager_beter', 'live', 'Dossiers afgerond in het kalenderjaar tot nu; reeks per maand van afronding', 'Dagelijks (HubSpot-sync)', 30, 'kpi_hs_tegel', 'kpi_acc_doorlooptijd_maand', 'Mediaan in dagen van aanmaken tot afronding, voor dossiers die nu in Verwerkt (archief) staan. Afronding is de sluitdatum van het ticket; de stapdatum van Verwerkt is te dun gevuld.', 'Eindstap Verwerkt is standaard tot ACC een andere eindstap bevestigt.', 1, CAST('2026-09-21' AS DATE), 'Gebouwd volgens briefing deel 4, gemeten per maand van afronding.', 'Verwerkt is de eindstap van een dossier; de sluitdatum van het ticket is het moment van afronding.'),
  (15, 'time_to_onboarding', 'Time to onboarding', 'operationeel', 'Klant', 'Mark', 'Mark', 'HubSpot', 'dagen', 'lager_beter', 'live', 'Onboardings afgerond in het kalenderjaar tot nu; reeks per kwartaal van afronding', 'Dagelijks (HubSpot-sync), reeks per kwartaal', 5, 'kpi_hs_tegel', 'kpi_onboarding_kwartaal', 'Mediaan in dagen van aanmaken van het onboardingticket tot de fase Onboard, gemeten op het moment van afronding.', 'Een paar trajecten die lang open stonden trekken de mediaan omhoog. AFC-onboarding heeft nog geen tickets.', 1, CAST('2026-09-21' AS DATE), 'Gebouwd volgens briefing deel 4, gemeten per kwartaal van afronding.', 'De fase Onboard betekent dat de klant live is. Het onboardingticket wordt aangemaakt bij het tekenen.'),
  (16, 'damage_rate', 'Damage rate inbound', 'team_awc', 'Kwaliteit', 'Edo', 'Edo', '7T', 'procent', 'lager_beter', 'live', 'Inbounds gelost in de laatste afgelopen maand', 'Nachtelijk uit 7T, maandcijfer na afloop van de maand', 30, 'kpi_awc_ops_tegel', 'kpi_awc_ops_maand', 'Aandeel geloste inbounds (Spare_Orders, Gelost = 1) met minstens één orderregelmutatie met reden MANCO - DAMAGED DELIVERED (Mutatiereden 35), geteld op orders. Schade door AWC (MANCO - DAMAGEDBYAWC, 34), niet geleverd (33) en onjuiste artikelinformatie (32) staan apart.', 'De manco-registratie loopt pas sinds januari 2026 goed; de lage percentages in januari en maart zijn deels onderregistratie. Dekt alleen inbound; voor uitslagschade is geen registratie gevonden.', 1, CAST('2026-09-22' AS DATE), 'v1: gebouwd op voorstel-definitie, nachtapp kpi_7t_naar_warehouse schrijft naar kpi_data.awc_operatie_maand.', 'Elke geconstateerde schade bij ontvangst wordt als manco met de juiste reden geregistreerd. Schade door AWC komt vrijwel niet voor (6 orders in 2026).'),
  (17, 'throughput', 'Throughput', 'team_awc', 'Operatie', 'Edo', 'Edo', '7T', 'aantal', 'neutraal', 'live', 'Afgeronde uitleveringen in de laatste afgelopen maand', 'Nachtelijk uit 7T, maandcijfer na afloop van de maand', 1, 'kpi_awc_ops_tegel', 'kpi_awc_ops_maand', 'Aantal afgeronde uitgaande orders (Logistieke_Orders, Statussoort Log, status 90 of hoger) per maand van aflevering. Inkomend staat ernaast: geloste inbounds en het deel met een verplaatsing.', 'De oude telling (8.553 ontvangsten) telde ook eigenaarswissels zonder fysieke beweging mee.', 1, CAST('2026-09-22' AS DATE), 'v1: gebouwd op voorstel-definitie, nachtapp kpi_7t_naar_warehouse.', 'Een logistieke order met status 90 of hoger is fysiek uitgeleverd. Tellen op orders, niet op orderregels of colli.'),
  (18, 'afc_zendingen', 'Zendingen', 'team_afc', 'Volume', 'Floor', 'Floor', 'Sprinter3000', 'aantal', 'neutraal', 'live', 'Zendingen met rapportdatum in de laatste afgesloten maand', 'Dagelijks (eigen Sprinter-sync), maandcijfer na afloop van de maand', 1, 'kpi_afc_sprinter_tegel', 'kpi_afc_sprinter_maand', 'Aantal zendingen in Sprinter3000 (sprinter_api.shipments) per maand van rapportdatum, zonder geannuleerde zendingen (status C).', 'Sprinter telt op rapportdatum, Cashweb op factuurdatum; maandaantallen lopen daardoor niet gelijk met de facturatie. Voor financiële maandomzet is Cashweb leidend.', 2, CAST('2026-11-12' AS DATE), 'v1: standaardconnector (schema sprinter3000), sinds augustus 2026 onvolledig doordat die maar 20 records per run ophaalt. v2: eigen sync via de Sprinter S-API (schema sprinter_api), historie vanaf 2023; omzet aug-okt 2026 sluit op Cashweb binnen 1,3%.', 'Status C betekent geannuleerd en telt niet mee. De betekenis van de Sprinter-codes is nog te bevestigen door Floor.'),
  (19, 'afc_modal_split', 'Modal split, aandeel weg', 'team_afc', 'Volume', 'Floor', 'Floor', 'Sprinter3000', 'procent', 'neutraal', 'live', 'Zendingen met rapportdatum in de laatste afgesloten maand', 'Dagelijks (eigen Sprinter-sync), maandcijfer na afloop van de maand', 30, 'kpi_afc_sprinter_tegel', 'kpi_afc_sprinter_maand', 'Aandeel zendingen over de weg (shipment_mode R) in alle zendingen van de maand, zonder geannuleerde. Zee (S) en lucht (A) staan in kpi_afc_sprinter_maand.', 'Zeevracht schommelt sterk per maand (2% tot 14%); kijk naar de trend, niet naar één maand.', 2, CAST('2026-11-12' AS DATE), 'v1: standaardconnector (schema sprinter3000), sinds augustus 2026 onvolledig. v2: eigen sync via de Sprinter S-API (schema sprinter_api).', 'Shipment_mode R is weg, S is zee, A is lucht. Nog te bevestigen door Floor.'),
  (20, 'afc_marge_per_zending', 'Marge per zending', 'team_afc', 'Marge', 'Floor', 'Floor', 'Sprinter3000', 'euro', 'hoger_beter', 'live', 'Zendingen met rapportdatum in de laatste afgesloten maand', 'Dagelijks (eigen Sprinter-sync), maandcijfer na afloop van de maand', 30, 'kpi_afc_sprinter_tegel', 'kpi_afc_sprinter_maand', 'Som van de brutomarge per zending (total_gpm_amount: verkoop min inkoop) gedeeld door het aantal zendingen in de maand, zonder geannuleerde.', 'Bedragen worden bij facturatie aangevuld; de meest recente maand kan nog stijgen. De zondagse sync haalt late wijzigingen op.', 2, CAST('2026-11-12' AS DATE), 'v1: standaardconnector (schema sprinter3000), sinds augustus 2026 onvolledig en vaak zonder bedragen. v2: eigen sync via de Sprinter S-API (schema sprinter_api).', 'Total_gpm_amount is verkoop min inkoop zoals Sprinter die per zending vastlegt.')) AS v(volgorde, kpi_code, naam, niveau, pijler, eigenaar, validator, bron, eenheid, richting, bouwstatus, venster, updatefrequentie, min_n, tegel_view, historie_view, definitie, kanttekening, definitie_versie, definitie_geldig_vanaf, wijziging, aanname)
